// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY users (PostgreSQL / Relational) {
  [PK ] user_id                BIGINT
  [IDX] email                  VARCHAR(255)
        api_key_hash           CHAR(64)
        tier                   ENUM('FREE','PRO')
        created_at             TIMESTAMPTZ
}

ENTITY short_urls (DynamoDB / Sharded SQL) {
  [PK ] short_code             VARCHAR(10)
  [FK ] user_id                BIGINT
        long_url               TEXT
  [IDX] expires_at             TIMESTAMPTZ
        created_at             TIMESTAMPTZ
}

ENTITY click_events (ClickHouse (Columnar)) {
  [PK ] event_id               UUID
  [FK ] short_code             VARCHAR(10)
  [IDX] clicked_at             DATETIME64
        country_iso            CHAR(2)
        user_agent             TEXT
}

// Relationships: users --(1 : N (owns))--> short_urls --(1 : N (logs clicks))--> click_events

/*
 * ==================== FLOW 1: WRITE PATH (ID GENERATION & BASE62) ====================
 *
 * Client -> WriteService -> LocalRangeAllocator (AtomicLong)
 *                                 | (When local range [start, end] exhausted)
 *                                 v
 *                           etcd / ZooKeeper (Atomically increments global counter by 100,000)
 * WriteService -> BijectiveScrambler(id) -> Base62Encoder -> Save to Cassandra -> Warm Redis
 *
 * ==================== FLOW 2: READ PATH (MULTI-TIER REDIRECT) ========================
 *
 * Client -> RedirectService -> L1 Caffeine Cache (Hit? Return 302 in 0.2ms)
 *                                 | Miss
 *                                 v
 *                              L2 Redis Cluster (Hit? Populate L1, Return 302 in 1.5ms)
 *                                 | Miss
 *                                 v
 *                              Bloom Filter Check (Definitely Not Present? Return 404 in 0.5ms)
 *                                 | Might Exist
 *                                 v
 *                              Cassandra DB (Read by PK short_code -> Populate Redis -> Return 302)
 */

package com.sdi.urlshortener.service;

import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.time.Instant;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

@Service
public class UrlShortenerService {

    private static final char[] BASE62 =
            "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ".toCharArray();
    private static final long OFFSET_7_CHAR = 56_800_235_584L; // 62^6, ensures at least 7 chars
    private static final String NULL_SENTINEL = "__NULL__";

    private final AtomicLong currentId = new AtomicLong(0);
    private volatile long rangeMaxId = 0;

    private final Cache<String, ShortUrlEntity> l1Cache = Caffeine.newBuilder()
            .maximumSize(10_000)
            .expireAfterWrite(Duration.ofSeconds(5))
            .build();

    private final StringRedisTemplate redis;
    private final ShortUrlRepository repository;
    private final RangeCoordinatorClient rangeCoordinator;
    private final KafkaTemplate<String, String> kafka;

    public UrlShortenerService(StringRedisTemplate redis,
                               ShortUrlRepository repository,
                               RangeCoordinatorClient rangeCoordinator,
                               KafkaTemplate<String, String> kafka) {
        this.redis = redis;
        this.repository = repository;
        this.rangeCoordinator = rangeCoordinator;
        this.kafka = kafka;
    }

    // ---------------- FLOW 1: COLLISION-FREE URL SHORTENING ----------------
    public CreateShortUrlResponse shortenUrl(Long userId, CreateShortUrlRequest req) {
        String shortCode;
        long uniqueId = -1L;

        if (req.customAlias() != null && !req.customAlias().isBlank()) {
            shortCode = req.customAlias();
            // Conditional write (Paxos LWT / DynamoDB attribute_not_exists) for custom alias
            boolean inserted = repository.insertIfNotExists(shortCode, req.longUrl(), userId, req.expiresAt());
            if (!inserted) {
                throw new IllegalArgumentException("Custom alias already taken: " + shortCode);
            }
        } else {
            uniqueId = nextUniqueId();
            long scrambledId = scrambleId(uniqueId) + OFFSET_7_CHAR;
            shortCode = encodeBase62(scrambledId);

            ShortUrlEntity entity = new ShortUrlEntity(
                    shortCode, uniqueId, req.longUrl(), userId,
                    req.redirectType() != null ? req.redirectType() : 302,
                    Instant.now(), req.expiresAt(), true
            );
            repository.save(entity);
        }

        // Write-warm Redis cache for 24 hours (newly created links are clicked immediately)
        redis.opsForValue().set("url:" + shortCode, req.longUrl(), 24, TimeUnit.HOURS);

        return new CreateShortUrlResponse(
                shortCode, "https://sho.rt/" + shortCode, req.longUrl(), req.expiresAt()
        );
    }

    private synchronized long nextUniqueId() {
        long next = currentId.incrementAndGet();
        if (next > rangeMaxId) {
            // Lease next 100,000 IDs from etcd/ZooKeeper
            IdRange range = rangeCoordinator.allocateNextRange(100_000);
            currentId.set(range.start());
            rangeMaxId = range.end();
            next = currentId.get();
        }
        return next;
    }

    // Bijective Feistel-like XOR scramble so sequential IDs don't look sequential
    private long scrambleId(long id) {
        id = ((id >>> 20) ^ id) * 0x45d9f3bL;
        id = ((id >>> 20) ^ id) & 0x1FFFFFFFFFFL; // Keep within 41-bit space (< 62^7)
        return id;
    }

    public static String encodeBase62(long num) {
        StringBuilder sb = new StringBuilder(7);
        while (num > 0) {
            sb.append(BASE62[(int) (num % 62)]);
            num /= 62;
        }
        return sb.reverse().toString();
    }

    // ---------------- FLOW 2: ULTRA-LOW-LATENCY REDIRECTION ----------------
    public ShortUrlEntity resolveShortCode(String shortCode, String userAgent, String country) {
        // 1. Check L1 Local Caffeine Cache (protects Redis against celebrity hot-key spikes)
        ShortUrlEntity cachedL1 = l1Cache.getIfPresent(shortCode);
        if (cachedL1 != null) {
            emitClickEventAsync(shortCode, userAgent, country);
            return cachedL1;
        }

        // 2. Check L2 Redis Cluster
        String redisKey = "url:" + shortCode;
        String cachedUrl = redis.opsForValue().get(redisKey);
        if (cachedUrl != null) {
            if (NULL_SENTINEL.equals(cachedUrl)) {
                throw new ResourceNotFoundException("Short URL does not exist: " + shortCode);
            }
            ShortUrlEntity entity = new ShortUrlEntity(
                    shortCode, 0L, cachedUrl, null, 302, Instant.now(), null, true);
            l1Cache.put(shortCode, entity);
            emitClickEventAsync(shortCode, userAgent, country);
            return entity;
        }

        // 3. Cache Miss -> Query Cassandra/DynamoDB by Partition Key
        ShortUrlEntity entity = repository.findByShortCode(shortCode)
                .filter(ShortUrlEntity::isActive)
                .filter(e -> e.expiresAt() == null || e.expiresAt().isAfter(Instant.now()))
                .orElse(null);

        if (entity == null) {
            // Cache negative lookup for 60s to block cache penetration attacks
            redis.opsForValue().set(redisKey, NULL_SENTINEL, 60, TimeUnit.SECONDS);
            throw new ResourceNotFoundException("Short URL not found or expired: " + shortCode);
        }

        // 4. Populate L2 & L1 caches
        redis.opsForValue().set(redisKey, entity.longUrl(), 24, TimeUnit.HOURS);
        l1Cache.put(shortCode, entity);
        emitClickEventAsync(shortCode, userAgent, country);
        return entity;
    }

    private void emitClickEventAsync(String shortCode, String userAgent, String country) {
        // Non-blocking send to Kafka ring buffer; never blocks the HTTP redirect thread
        kafka.send("url-click-events", shortCode,
                "{\"code\":\"" + shortCode + "\",\"country\":\"" + country + "\"}");
    }
}
